import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    vals = data[1:]
    m = max(vals)

    spf = list(range(m + 1))
    for p in range(2, int(m ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, m + 1, p):
                if spf[x] == x:
                    spf[x] = p

    nim_sum = 0
    for x in vals:
        omega = 0
        while x > 1:
            x //= spf[x]
            omega += 1
        nim_sum ^= omega

    print("Anna" if nim_sum else "Bruno")

main()

