from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        heap = []
        gain = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for left, idx in by_right[right]:
                heapq.heappush(heap, (-left, idx))

            if heap:
                largest = -heap[0][0]
                second_largest = -heap[1][0] if len(heap) > 1 else 0
                total += right - largest
                gain[heap[0][1]] += largest - second_largest
            else:
                total += right

        return total + max(gain)

