from typing import List
import heapq
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right=[[] for _ in range(n+1)]
        for i,(a,b) in enumerate(conflictingPairs):
            if a>b: a,b=b,a
            by_right[b].append((a,i))
        h=[]
        gain=[0]*len(conflictingPairs)
        base=0
        for r in range(1,n+1):
            for a,i in by_right[r]: heapq.heappush(h,(-a,i))
            if h:
                top=-h[0][0]
                second=-h[1][0] if len(h)>1 else 0
                base+=r-top
                gain[h[0][1]]+=top-second
            else: base+=r
        return base+max(gain)

