import sys

def main():
    input=sys.stdin.buffer.readline
    N,M,Q=map(int,input().split())
    edges=[]
    for _ in range(M):
        a,b,c=map(int,input().split())
        edges.append((a-1,b-1,c))
    queries=[]
    closed=[False]*M
    for _ in range(Q):
        t,*v=map(int,input().split())
        if t==1:
            i=v[0]-1
            closed[i]=True
            queries.append((1,i))
        else:
            queries.append((2,v[0]-1,v[1]-1))
    INF=10**30
    d=[[INF]*N for _ in range(N)]
    for i in range(N): d[i][i]=0
    for k,(a,b,c) in enumerate(edges):
        if not closed[k]:
            d[a][b]=d[b][a]=c
    for k in range(N):
        dk=d[k]
        for i in range(N):
            dik=d[i][k]
            if dik==INF: continue
            di=d[i]
            for j in range(N):
                x=dik+dk[j]
                if x<di[j]: di[j]=x
    ans=[]
    for q in reversed(queries):
        if q[0]==2:
            x,y=q[1],q[2]
            ans.append(str(d[x][y] if d[x][y]<INF else -1))
        else:
            a,b,c=edges[q[1]]
            au=[d[i][a] for i in range(N)]
            bu=[d[i][b] for i in range(N)]
            for i in range(N):
                di=d[i]
                x=au[i]+c
                y=bu[i]+c
                for j in range(N):
                    z=x+bu[j]
                    if z<di[j]: di[j]=z
                    z=y+au[j]
                    if z<di[j]: di[j]=z
    sys.stdout.write('\n'.join(reversed(ans)))
if __name__=='__main__': main()

