class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # Pascal triangle for binomial coefficients up to n.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        good = [False] * (n + 1)
        for t in range(1, n + 1):
            v = t
            steps = 0
            while v > 1:
                v = v.bit_count()
                steps += 1
            good[t] = steps + 1 <= k

        ans = 0
        for target in range(1, n + 1):
            if not good[target]:
                continue
            ones_left = target
            ways = 0
            for i, ch in enumerate(s):
                if ch == '1':
                    remaining = n - i - 1
                    need = ones_left
                    if 0 <= need <= remaining:
                        ways += comb[remaining][need]
                    ones_left -= 1
                    if ones_left < 0:
                        break
            ans = (ans + ways) % MOD
        return ans

