import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    people = [(next(it), next(it)) for _ in range(m)]
    queries = [(next(it), next(it)) for _ in range(q)]
    out = []
    for left, right in queries:
        parent = list(range(n + 1))
        size = [1] * (n + 1)
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        for idx in range(left - 1, right):
            a, b = people[idx]
            x, y = find(a), find(b)
            if x != y:
                if size[x] < size[y]:
                    x, y = y, x
                parent[y] = x
                size[x] += size[y]
        edges = [set() for _ in range(n + 1)]
        indeg = [0] * (n + 1)
        impossible = False
        for idx in range(left - 1, right):
            a, b = people[idx]
            root = find(a)
            if a < b:
                lo, hi = a + 1, b - 1
                for p in range(lo, hi + 1):
                    v = find(p)
                    if v == root:
                        impossible = True
                        break
                    if v not in edges[root]:
                        edges[root].add(v)
                        indeg[v] += 1
            else:
                lo, hi = b + 1, a - 1
                for p in range(lo, hi + 1):
                    v = find(p)
                    if v == root:
                        impossible = True
                        break
                    if root not in edges[v]:
                        edges[v].add(root)
                        indeg[root] += 1
        if impossible:
            out.append('No')
            continue
        roots = {find(i) for i in range(1, n + 1)}
        dq = deque(v for v in roots if indeg[v] == 0)
        seen = 0
        while dq:
            u = dq.popleft()
            seen += 1
            for v in edges[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    dq.append(v)
        out.append('Yes' if seen == len(roots) else 'No')
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

