    input = sys.stdin.readline
    n = int(input())
    g = [input().strip() for _ in range(n)]

    inc = [[[] for _ in range(26)] for _ in range(n)]
    out = [[[] for _ in range(26)] for _ in range(n)]
    for i in range(n):
        for j, ch in enumerate(g[i]):
            if ch != '-':
                k = ord(ch) - 97
                out[i][k].append(j)
                inc[j][k].append(i)

    d = [[-1] * n for _ in range(n)]
    q = deque()
    for i in range(n):
        d[i][i] = 0
        q.append((i, i))
    for i in range(n):
        for j, ch in enumerate(g[i]):
            if ch != '-' and d[i][j] < 0:
                d[i][j] = 1
                q.append((i, j))

    while q:
        a, b = q.popleft()
        nd = d[a][b] + 2
        ia = inc[a]
        ob = out[b]
        for k in range(26):
            xs = ia[k]
            ys = ob[k]
            if xs and ys:
                for x in xs:
                    row = d[x]
                    for y in ys:
                        if row[y] < 0:
                            row[y] = nd
                            q.append((x, y))

    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in d))

