import sys, heapq

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    H,W,X=data[:3]
    P,Q=data[3]-1,data[4]-1
    a=data[5:]
    start=P*W+Q
    strength=a[start]
    seen=bytearray(H*W)
    seen[start]=1
    heap=[]
    def add_neighbors(idx):
        r,c=divmod(idx,W)
        if r>0:
            v=idx-W
            if not seen[v]: seen[v]=1; heapq.heappush(heap,(a[v],v))
        if r+1<H:
            v=idx+W
            if not seen[v]: seen[v]=1; heapq.heappush(heap,(a[v],v))
        if c>0:
            v=idx-1
            if not seen[v]: seen[v]=1; heapq.heappush(heap,(a[v],v))
        if c+1<W:
            v=idx+1
            if not seen[v]: seen[v]=1; heapq.heappush(heap,(a[v],v))
    add_neighbors(start)
    while heap:
        val,idx=heapq.heappop(heap)
        if val*X >= strength:
            break
        strength+=val
        add_neighbors(idx)
    print(strength)

if __name__=='__main__': main()

