from typing import List
from functools import lru_cache
import sys

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        sys.setrecursionlimit(10000)
        n, m = len(grid), len(grid[0])
        # Clockwise order in matrix coordinates: SE -> SW -> NW -> NE.
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))

        @lru_cache(None)
        def best_from(r: int, c: int, d: int, need: int, can_turn: bool) -> int:
            # The current cell has value need. Count it and extend if possible.
            answer = 1
            next_value = 0 if need == 2 else 2
            options = [(d, can_turn)]
            if can_turn:
                options.append(((d + 1) % 4, False))
            for nd, remains_available in options:
                dr, dc = dirs[nd]
                nr, nc = r + dr, c + dc
                if (0 <= nr < n and 0 <= nc < m
                        and grid[nr][nc] == next_value):
                    answer = max(answer, 1 + best_from(
                        nr, nc, nd, next_value, remains_available))
            return answer

        result = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                result = max(result, 1)
                for d, (dr, dc) in enumerate(dirs):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                        result = max(result, 1 + best_from(nr, nc, d, 2, True))
        return result

