from math import factorial

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = set(range(1, n + 1, 2))
        evens = set(range(2, n + 1, 2))
        ans = []
        prev_odd = None

        for pos in range(n):
            remaining_slots = n - pos - 1
            found = False

            for x in sorted(odds | evens):
                is_odd = x & 1
                if prev_odd is not None and is_odd == prev_odd:
                    continue

                remaining_odds = len(odds) - is_odd
                remaining_evens = len(evens) - (not is_odd)

                # After x, the remaining suffix must alternate, beginning
                # with the parity opposite to x.
                starts_odd = not is_odd
                odd_slots = ((remaining_slots + 1) // 2
                             if starts_odd else remaining_slots // 2)
                even_slots = remaining_slots - odd_slots

                if remaining_odds == odd_slots and remaining_evens == even_slots:
                    block = factorial(remaining_odds) * factorial(remaining_evens)
                else:
                    block = 0

                if k > block:
                    k -= block
                else:
                    ans.append(x)
                    if is_odd:
                        odds.remove(x)
                    else:
                        evens.remove(x)
                    prev_odd = is_odd
                    found = True
                    break

            if not found:
                return []

        return ans

