    def distanceSum(self, m: int, n: int, k: int) -> int:
        N = m * n

        def comb(a, b):
            fact = [1] * (a + 1)
            for i in range(1, a + 1):
                fact[i] = fact[i - 1] * i % MOD
            inv = [1] * (a + 1)
            inv[a] = pow(fact[a], MOD - 2, MOD)
            for i in range(a, 0, -1):
                inv[i - 1] = inv[i] * i % MOD
            return fact[a] * inv[b] % MOD * inv[a - b] % MOD

        pairdist = (
            n * n * (m * (m * m - 1) // 6)
            + m * m * (n * (n * n - 1) // 6)
        ) % MOD
        return pairdist * comb(N - 2, k - 2) % MOD

