class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        weights = []
        for i in range(m):
            j = n - 1 - i
            if i == j:
                weights.append(powers[i])
            else:
                weights.append((powers[i] + powers[j]) % k)

        full_mask = (1 << k) - 1
        suffix = [0] * (m + 1)
        suffix[m] = 1  # Only residue 0 is reachable with no digits left.

        for i in range(m - 1, -1, -1):
            lo = 1 if i == 0 else 0
            weight = weights[i]
            reachable = 0
            for digit in range(lo, 10):
                shift = digit * weight % k
                mask = suffix[i + 1]
                if shift:
                    mask = ((mask << shift) | (mask >> (k - shift))) & full_mask
                reachable |= mask
            suffix[i] = reachable

        digits = []
        residue = 0
        for i, weight in enumerate(weights):
            lo = 1 if i == 0 else 0
            for digit in range(9, lo - 1, -1):
                new_residue = (residue + digit * weight) % k
                needed = (-new_residue) % k
                if (suffix[i + 1] >> needed) & 1:
                    digits.append(str(digit))
                    residue = new_residue
                    break

        left = ''.join(digits)
        if n % 2:
            return left + left[:-1][::-1]
        return left + left[::-1]

