from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # next greater element to the right
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                nxt[i] = stack[-1]
            stack.append(i)

        log = n.bit_length()
        jump = [nxt]
        total = [[nums[i] * (nxt[i] - i) for i in range(n)]]
        for _ in range(1, log):
            prev_jump = jump[-1]
            prev_total = total[-1]
            cur_jump = [n] * n
            cur_total = [0] * n
            for i in range(n):
                mid = prev_jump[i]
                if mid < n:
                    cur_jump[i] = prev_jump[mid]
                    cur_total[i] = prev_total[i] + prev_total[mid]
                else:
                    cur_total[i] = prev_total[i]
            jump.append(cur_jump)
            total.append(cur_total)

        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        def cost(left: int, right: int) -> int:
            i = left
            raised_sum = 0
            for p in range(log - 1, -1, -1):
                dest = jump[p][i]
                if dest <= right:
                    raised_sum += total[p][i]
                    i = dest
            raised_sum += nums[i] * (right - i + 1)
            return raised_sum - (prefix[right + 1] - prefix[left])

        answer = 0
        right_bound = 0
        for left in range(n):
            lo, hi = right_bound, n - 1
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if cost(left, mid) <= k:
                    lo = mid
                else:
                    hi = mid - 1
            right_bound = lo
            answer += lo - left + 1
        return answer

