from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))

            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j

            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        A, B, C = map(occurrences, (a, b, c))
        ans = n + 1
        for st in A:
            bi = bisect_left(B, st + len(a))
            if bi == len(B):
                continue
            mid = B[bi]
            ci = bisect_left(C, mid + len(b))
            if ci == len(C):
                continue
            end = C[ci] + len(c)
            ans = min(ans, end - st)

        return -1 if ans == n + 1 else ans

