import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    pos = 2
    for _ in range(m):
        x, y, z = data[pos] - 1, data[pos + 1] - 1, data[pos + 2]
        pos += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    potential = [-1] * n
    answer = [0] * n
    for start in range(n):
        if potential[start] != -1:
            continue
        potential[start] = 0
        queue = [start]
        component = []
        for v in queue:
            component.append(v)
            for w, z in graph[v]:
                expected = potential[v] ^ z
                if potential[w] == -1:
                    potential[w] = expected
                    queue.append(w)
                elif potential[w] != expected:
                    print(-1)
                    return

        size = len(component)
        offset = 0
        for bit in range(30):
            ones = sum((potential[v] >> bit) & 1 for v in component)
            if ones > size - ones:
                offset |= 1 << bit
        for v in component:
            answer[v] = potential[v] ^ offset

    print(*answer)

if __name__ == '__main__':
    main()

