from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        order = []
        left = [0] * n
        size = [1] * n
        stack = [(0, 0)]
        while stack:
            v, phase = stack.pop()
            if phase == 0:
                stack.append((v, 1))
                for u in reversed(children[v]):
                    stack.append((u, 0))
            else:
                size[v] = 1 + sum(size[u] for u in children[v])
                left[v] = len(order) - size[v] + 1
                order.append(s[v])

        t = ''.join(order)
        m = len(t)

        # Manacher radii for odd-length palindromes.
        d1 = [0] * m
        l, r = 0, -1
        for i in range(m):
            k = 1 if i > r else min(d1[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < m and t[i - k] == t[i + k]:
                k += 1
            d1[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1

        # Manacher radii for even-length palindromes; center is between i-1 and i.
        d2 = [0] * m
        l, r = 0, -1
        for i in range(m):
            k = 0 if i > r else min(d2[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < m and t[i - k - 1] == t[i + k]:
                k += 1
            d2[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1

        ans = [False] * n
        for v in range(n):
            length = size[v]
            start = left[v]
            if length % 2:
                ans[v] = d1[start + length // 2] >= length // 2 + 1
            else:
                ans[v] = d2[start + length // 2] >= length // 2
        return ans
